Write-Host "=== IMA ENV VARS ==="; Get-ChildItem Env: | ForEach-Object { if ($_.Name -like "*IMA*") { "$($_.Name) = $($_.Value)" } }; Write-Host "=== CONFIG FILES ==="; $cidPath = Join-Path $env:USERPROFILE ".config/ima/client_id"; $keyPath = Join-Path $env:USERPROFILE ".config/ima/api_key"; if (Test-Path $cidPath) { Write-Host "client_id:" (Get-Content $cidPath -Raw) } else { Write-Host "client_id: NOT FOUND" }; if (Test-Path $keyPath) { Write-Host "api_key:" (Get-Content $keyPath -Raw) } else { Write-Host "api_key: NOT FOUND" }